#include <cstdio>
#include <cfloat>
#include <cstring>
using namespace std;

char f[10][21];
int n, w[10], s[10], a[10], b[10];
double maxg;

void dfs(int x, int tw, int m, double g, int used) {
    if (m == n) {
        if (maxg < g) {
            maxg = g;
            memcpy(b, a, sizeof(b));
        }
        return;
    }
    if (x >= n) return;

    if ((used & (1 << x)) == 0 && tw <= s[x]) {  // Check if x is not used
        // Include current item
        a[m] = x;
        dfs(0, tw + w[x], m + 1, g + w[x] * (m + 1), used | (1 << x));
    }
    // Skip current item
    dfs(x + 1, tw, m, g, used);
}

int main() {
    while (1) {
        scanf("%d", &n);
        if (!n) break;
        for (int i = 0; i < n; i++) {
            scanf("%s %d %d", f[i], &w[i], &s[i]);
        }
        maxg = -DBL_MAX;
        dfs(0, 0, 0, 0., 0);  // Pass initial used state as 0
        for (int i = n - 1; i >= 0; i--) {
            printf("%s\n", f[b[i]]);
        }
    }
    return 0;
}

