array<char[21], 10> f;
array<int, 10> w, s, a, b;
int n;
double maxg;

void dfs(int x, int tw, int m, double g, array<bool, 10>& u) {
    if (m == n) {
        if (maxg < g) {
            maxg = g;
            memcpy(b.data(), a.data(), sizeof(int) * n);
        }
        return;
    }
    if (x >= n) return;

    if (!u[x] && tw <= s[x]) {
        u[x] = true;
        tw += w[x];
        a[m] = x;
        dfs(0, tw, m + 1, g + w[x] * (m + 1), u);
        tw -= w[x];
        u[x] = false;
    }
    dfs(x + 1, tw, m, g, u);
}

int main() {
    do {
        scanf("%d", &n);
        if (n == 0) break;
        for (int i = 0; i < n; i++) {
            scanf("%s %d %d", f[i], &w[i], &s[i]);
        }
        array<bool, 10> u = {false};
        maxg = -DBL_MAX;
        dfs(0, 0, 0, 0., u);
        for (int i = n - 1; i >= 0; i--) {
            printf("%s\n", f[b[i]]);
        }
    } while (true);
    return 0;
}

